    !(await verifyGitHubWebhookSignature({
      body: body.bytes,
      secret,
      signatureHeader,
    }))
  ) {
    return rejected(401);
  }

  return {
    body: new TextDecoder().decode(body.bytes),
    deliveryId,
    event,
    kind: "authenticated",
  };
}

