import { resolveSecretText, type SecretTextBinding } from "@cyspbot/github/secrets";
import type { GitHubIssueCommentStatusReactionJob } from "@cyspbot/github-webhook-jobs";
import { readRequestBodyUpTo } from "@cyspbot/http/request-body";
import { verifyGitHubWebhookSignature } from "./signature.ts";
import { classifyStatusReactionJob } from "./status-reaction.ts";

const maxWebhookBodyBytes = 256 * 1024;

type WebhookAcceptedBody = { accepted: true; event?: string };

interface AuthenticatedWebhookEnvelope {
  body: string;
  deliveryId: string;
  event: string;
  kind: "authenticated";
}

interface GitHubWebhookJobQueue {
  send(
    message: GitHubIssueCommentStatusReactionJob,
    options?: { contentType?: "json" },
  ): Promise<unknown>;
}

export interface GitHubWebhookReceiverBaseEnv {
  GITHUB_APP_ID: string;
  GITHUB_WEBHOOK_JOBS: GitHubWebhookJobQueue;
  GITHUB_WEBHOOK_SECRET?: SecretTextBinding;
}

export interface GitHubWebhookReceiverDependencies {
  now(): Date;
}

export type WebhookDeliveryAcceptanceResult =
  | {
      body: WebhookAcceptedBody;
      kind: "accepted";
      status: 202;
    }
  | {
      kind: "rejected";
      status: number;
    };

type WebhookDeliveryRejection = Extract<WebhookDeliveryAcceptanceResult, { kind: "rejected" }>;

export async function acceptGitHubWebhookDelivery<Env extends GitHubWebhookReceiverBaseEnv>(
  request: Request,
  env: Env,
  dependencies: GitHubWebhookReceiverDependencies,
): Promise<WebhookDeliveryAcceptanceResult> {
  const secret = await resolveSecretText(env.GITHUB_WEBHOOK_SECRET);
  const receivedAt = dependencies.now().toISOString();

  if (secret === undefined || secret.length === 0) {
    console.error("webhook_receiver_not_configured", { occurred_at: receivedAt });
    return rejected(500);
  }

  const envelope = await authenticateWebhookEnvelope({
    env,
    request,
    secret,
  });

  if (envelope.kind !== "authenticated") {
    logWebhookRejection(envelope.status, request);
    return envelope;
  }

  let payload: unknown;

  try {
    payload = JSON.parse(envelope.body);
  } catch {
    logWebhookRejection(400, request, envelope);
    return rejected(400);
  }

  if (envelope.event === "ping") {
    return accepted({ accepted: true, event: envelope.event });
  }

  const job = classifyStatusReactionJob(envelope.event, envelope.deliveryId, payload);
  if (job !== undefined) {
    try {
      await env.GITHUB_WEBHOOK_JOBS.send(job, { contentType: "json" });
    } catch (error) {
      console.error("github_webhook_job_enqueue_failed", {
        deliveryId: envelope.deliveryId,
        error: error instanceof Error ? error.name : typeof error,
        event: envelope.event,
      });
      return rejected(503);
    }
  }

  return accepted({ accepted: true });
}

async function authenticateWebhookEnvelope<Env extends GitHubWebhookReceiverBaseEnv>(input: {
  env: Env;
  request: Request;
  secret: string;
}): Promise<AuthenticatedWebhookEnvelope | WebhookDeliveryAcceptanceResult> {
  const { env, request, secret } = input;

  if (!isJsonContentType(request.headers.get("content-type"))) {
    return rejected(415);
  }

  const event = request.headers.get("x-github-event");
  const deliveryId = request.headers.get("x-github-delivery");
  const signatureHeader = request.headers.get("x-hub-signature-256");
  const targetId = request.headers.get("x-github-hook-installation-target-id");
  const targetType = request.headers.get("x-github-hook-installation-target-type");
  const body = await readRequestBodyUpTo(request, maxWebhookBodyBytes);

  if (!body.ok) {
    return rejected(body.status);
  }

  if (event === null || deliveryId === null || signatureHeader === null) {
    return rejected(400);
  }

  if (targetType !== "integration" || targetId !== env.GITHUB_APP_ID) {
    return rejected(401);
  }

  if (
    !(await verifyGitHubWebhookSignature({
      body: body.bytes,
      secret,
      signatureHeader,
    }))
  ) {
    return rejected(401);
  }

  return {
    body: new TextDecoder().decode(body.bytes),
    deliveryId,
    event,
    kind: "authenticated",
  };
}

function logWebhookRejection(
  status: number,
  request: Request,
  envelope?: AuthenticatedWebhookEnvelope,
): void {
  console.warn("github_webhook_rejected", {
    deliveryId: envelope?.deliveryId ?? request.headers.get("x-github-delivery"),
    event: envelope?.event ?? request.headers.get("x-github-event"),
    rayId: request.headers.get("cf-ray"),
    status,
  });
}

function accepted(
  body: WebhookAcceptedBody,
): Extract<WebhookDeliveryAcceptanceResult, { kind: "accepted" }> {
  return {
    body,
    kind: "accepted",
    status: 202,
  };
}

function rejected(status: number): WebhookDeliveryRejection {
  return {
    kind: "rejected",
    status,
  };
}

function isJsonContentType(contentType: string | null): boolean {
  if (contentType === null) {
    return false;
  }

  return contentType.split(";", 1)[0]?.trim().toLowerCase() === "application/json";
}
import { describe, expect, it } from "vitest";

import type { GitHubIssueCommentStatusReactionJob } from "@cyspbot/github-webhook-jobs";
import {
  acceptGitHubWebhookDelivery,
  type GitHubWebhookReceiverDependencies,
} from "@cyspbot/github-webhook-receiver/github-webhooks/acceptance";
import { githubWebhookHeaders } from "./support/webhook.ts";

interface TestWebhookEnv {
  GITHUB_APP_ID: string;
  GITHUB_WEBHOOK_JOBS: {
    send(
      message: GitHubIssueCommentStatusReactionJob,
      options?: { contentType?: "json" },
    ): Promise<unknown>;
  };
  GITHUB_WEBHOOK_SECRET: string | SecretsStoreSecret;
}

const testWebhookEnv = {
  GITHUB_APP_ID: "000000",
  GITHUB_WEBHOOK_JOBS: {
    send: async () => ({}),
  },
  GITHUB_WEBHOOK_SECRET: "test-webhook-secret",
} satisfies TestWebhookEnv;

describe("webhook delivery acceptance", () => {
  it("acknowledges signed non-ping webhook deliveries without dispatching", async () => {
    const body = JSON.stringify({
      action: "opened",
      issue: {
        number: 12,
      },
    });

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "test-webhook-secret", "issues", "delivery-issues"),
        method: "POST",
      }),
      testWebhookEnv,
      testDependencies(),
    );

    expect(result).toEqual({
      body: { accepted: true },
      kind: "accepted",
      status: 202,
    });
  });

  it("accepts signed github ping webhook deliveries", async () => {
    const body = JSON.stringify({
      hook: {
        active: true,
      },
      zen: "Speak like a human.",
    });

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "test-webhook-secret", "ping"),
        method: "POST",
      }),
      testWebhookEnv,
      testDependencies(),
    );

    expect(result).toEqual({
      body: { accepted: true, event: "ping" },
      kind: "accepted",
      status: 202,
    });
  });

  it("enqueues a job for a newly created status comment", async () => {
    const jobs: GitHubIssueCommentStatusReactionJob[] = [];
    const body = JSON.stringify({
      action: "created",
      comment: {
        body: "  /cyspbot status  ",
        id: 42,
      },
      repository: {
        name: "cyspbot",
        owner: {
          login: "chikachow",
        },
      },
    });

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "test-webhook-secret", "issue_comment", "delivery-job"),
        method: "POST",
      }),
      {
        ...testWebhookEnv,
        GITHUB_WEBHOOK_JOBS: {
          send: async (job) => {
            jobs.push(job);
          },
        },
      },
      testDependencies(),
    );

    expect(result).toEqual({
      body: { accepted: true },
      kind: "accepted",
      status: 202,
    });
    expect(jobs).toEqual([
      {
        commentId: 42,
        deliveryId: "delivery-job",
        kind: "github.issue-comment.status-reaction",
        repository: {
          name: "cyspbot",
          owner: "chikachow",
        },
        version: 1,
      },
    ]);
  });

  it("returns service unavailable when the status job cannot be enqueued", async () => {
    const body = JSON.stringify({
      action: "created",
      comment: {
        body: "/cyspbot status",
        id: 42,
      },
      repository: {
        name: "cyspbot",
        owner: {
          login: "chikachow",
        },
      },
    });

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "test-webhook-secret", "issue_comment"),
        method: "POST",
      }),
      {
        ...testWebhookEnv,
        GITHUB_WEBHOOK_JOBS: {
          send: async () => {
            throw new Error("queue unavailable");
          },
        },
      },
      testDependencies(),
    );

    expect(result).toEqual({
      kind: "rejected",
      status: 503,
    });
  });

  it("reads the webhook secret from Cloudflare Secrets Store when bound", async () => {
    const body = JSON.stringify({
      hook: {
        active: true,
      },
      zen: "Speak like a human.",
    });

    const result = await acceptGitHubWebhookDelivery(
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "test-webhook-secret", "ping"),
        method: "POST",
      }),
      {
        GITHUB_APP_ID: testWebhookEnv.GITHUB_APP_ID,
        GITHUB_WEBHOOK_JOBS: testWebhookEnv.GITHUB_WEBHOOK_JOBS,
        GITHUB_WEBHOOK_SECRET: {
          get: async () => "test-webhook-secret",
        },
      },
      testDependencies(),
    );

    expect(result).toEqual({
      body: { accepted: true, event: "ping" },
      kind: "accepted",
      status: 202,
    });
  });

  it("accepts repeated signed webhook delivery ids", async () => {
    const body = JSON.stringify({
      action: "opened",
    });
    const request = () =>
      new Request("https://example.test/github/webhooks", {
        body,
        headers: githubWebhookHeaders(body, "test-webhook-secret", "issues", "delivery-repeat"),
        method: "POST",
