import { githubActionsOidcProviderRegistration } from "./oidc-provider-registrations.ts";
import { createGitHubRepositoryResource } from "@github-app-token-broker/github/installation-access-token-request";
import {
  claimEquals,
  claimOneOf,
  compileTokenIssuancePolicy,
  githubRepositoryResourceConstraint,
  oidcSubjectTokenConstraint,
  type PermitStatementDefinition,
} from "@github-app-token-broker/token-issuance-policy";

type GitHubActionsWorkflowFileName = `${string}.${"yml" | "yaml"}`;
type GitHubRepositoryFullName = `${string}/${string}`;

interface DeploymentRepositoryUpdatePermitStatementsOptions {
  readonly deploymentRepositoryFullName: GitHubRepositoryFullName;
  readonly updateTriggerWorkflowFileName: GitHubActionsWorkflowFileName;
  readonly updateTriggerRepositoryFullName: GitHubRepositoryFullName;
  readonly updateWorkflowFileName: GitHubActionsWorkflowFileName;
}

interface GitHubActionsMainBranchWorkflowPermitStatementOptions {
  readonly eventNames: readonly string[];
  readonly permissions: PermitStatementDefinition["permissions"];
  readonly resourceRepositoryFullName: GitHubRepositoryFullName;
  readonly workflowFileName: GitHubActionsWorkflowFileName;
  readonly workflowRepositoryFullName: GitHubRepositoryFullName;
}

const mainBranchGitRef = "refs/heads/main";
const pullRequestAuthoringPermissions = {
  contents: "write",
  pull_requests: "write",
} as const;

export const tokenIssuancePolicy = compileTokenIssuancePolicy([
  dependencyUpdatePermitStatement("chikachow/github-app-token-broker", "pnpm-up.yml"),
  ...deploymentRepositoryUpdatePermitStatements({
    deploymentRepositoryFullName: "chikachow/github-app-token-broker-deploy",
    updateTriggerWorkflowFileName: "run-github-app-token-broker-deploy-update.yml",
    updateTriggerRepositoryFullName: "chikachow/github-app-token-broker",
    updateWorkflowFileName: "update-github-app-token-broker.yml",
  }),
  dependencyUpdatePermitStatement("chikachow/cyspbot", "pnpm-up.yml"),
  ...deploymentRepositoryUpdatePermitStatements({
    deploymentRepositoryFullName: "chikachow/cyspbot-deploy",
    updateTriggerWorkflowFileName: "run-cyspbot-deploy-update.yml",
    updateTriggerRepositoryFullName: "chikachow/cyspbot",
    updateWorkflowFileName: "update-cyspbot.yml",
  }),
  dependencyUpdatePermitStatement("chikachow/cloudflare-workload-identity", "pnpm-up.yml"),
  ...deploymentRepositoryUpdatePermitStatements({
    deploymentRepositoryFullName: "chikachow/cloudflare-workload-identity-deploy",
    updateTriggerWorkflowFileName: "run-cloudflare-workload-identity-deploy-update.yml",
    updateTriggerRepositoryFullName: "chikachow/cloudflare-workload-identity",
    updateWorkflowFileName: "update-cloudflare-workload-identity.yml",
  }),
  dependencyUpdatePermitStatement("chikachow/cloudflare-workload-identity-deploy", "pnpm-up.yml"),
  dependencyUpdatePermitStatement("chikachow/cyspbot-app-token-action", "pnpm-up.yml"),
  dependencyUpdatePermitStatement("cysp/graphql-schema-registry", "pnpm-up.yml"),
  dependencyUpdatePermitStatement(
    "cysp/terraform-provider-braze",
    "update-indirect-dependencies.yml",
  ),
  dependencyUpdatePermitStatement(
    "cysp/terraform-provider-censusworkspace",
    "update-indirect-dependencies.yml",
  ),
  dependencyUpdatePermitStatement(
    "cysp/terraform-provider-contentful",
    "update-indirect-dependencies.yml",
  ),
  dependencyUpdatePermitStatement(
    "cysp/terraform-provider-typesense",
    "update-indirect-dependencies.yml",
  ),
]);

function dependencyUpdatePermitStatement(
  repositoryFullName: GitHubRepositoryFullName,
  workflowFileName: GitHubActionsWorkflowFileName,
): PermitStatementDefinition {
  return githubActionsMainBranchWorkflowPermitStatement({
    eventNames: ["schedule", "workflow_dispatch"],
    permissions: pullRequestAuthoringPermissions,
    resourceRepositoryFullName: repositoryFullName,
    workflowFileName,
    workflowRepositoryFullName: repositoryFullName,
  });
}

function deploymentRepositoryUpdatePermitStatements(
  options: DeploymentRepositoryUpdatePermitStatementsOptions,
): readonly PermitStatementDefinition[] {
  return [
    githubActionsMainBranchWorkflowPermitStatement({
      eventNames: ["workflow_run", "workflow_dispatch"],
      permissions: { actions: "write" },
      resourceRepositoryFullName: options.deploymentRepositoryFullName,
      workflowFileName: options.updateTriggerWorkflowFileName,
      workflowRepositoryFullName: options.updateTriggerRepositoryFullName,
    }),
    githubActionsMainBranchWorkflowPermitStatement({
      eventNames: ["workflow_dispatch"],
      permissions: pullRequestAuthoringPermissions,
      resourceRepositoryFullName: options.deploymentRepositoryFullName,
      workflowFileName: options.updateWorkflowFileName,
      workflowRepositoryFullName: options.deploymentRepositoryFullName,
    }),
  ];
}

function githubActionsMainBranchWorkflowPermitStatement(
  options: GitHubActionsMainBranchWorkflowPermitStatementOptions,
): PermitStatementDefinition {
  const resourceParts = parseGitHubRepositoryFullName(options.resourceRepositoryFullName);
  const workflowParts = parseGitHubRepositoryFullName(options.workflowRepositoryFullName);

  if (resourceParts === null || workflowParts === null) {
    throw new TypeError("invalid GitHub repository full_name");
  }

  const [resourceOwner, resourceRepository] = resourceParts;

  return {
    permissions: options.permissions,
    resource: githubRepositoryResourceConstraint(resourceOwner, resourceRepository),
    subjectToken: oidcSubjectTokenConstraint(
      githubActionsOidcProviderRegistration.issuer,
      claimEquals("repository", options.workflowRepositoryFullName),
      claimOneOf("event_name", options.eventNames),
      claimEquals("ref_type", "branch"),
      claimEquals("ref", mainBranchGitRef),
      claimEquals(
        "workflow_ref",
        `${options.workflowRepositoryFullName}/.github/workflows/${options.workflowFileName}@${mainBranchGitRef}`,
      ),
    ),
  };
}

export function parseGitHubRepositoryFullName(
  fullName: string,
): readonly [owner: string, repository: string] | null {
  const parts = fullName.split("/");

  if (parts.length !== 2 || parts[0] === undefined || parts[1] === undefined) {
    return null;
  }

  try {
    const resource = createGitHubRepositoryResource({
      owner: parts[0],
      repository: parts[1],
    });

    return [resource.owner, resource.repository];
  } catch {
    return null;
  }
}
import { describe, expect, it } from "vitest";

import { tokenIssuancePolicy } from "../src/token-issuance-policy.ts";
import { tokenIssuancePolicyPermits } from "@github-app-token-broker/token-issuance-policy";
import { githubActionsOidcProviderRegistration } from "@github-app-token-broker/oidc-provider-github-actions";
import type { GitHubInstallationPermissions } from "@github-app-token-broker/github/installation-access-token-request";
import {
  configuredPermitStatementExpectations,
  requestForExpectation,
  subjectTokenForExpectation,
} from "./configured-token-issuance-policy-expectations.ts";

const standardPermissionNames = ["actions", "contents", "pull_requests"] as const;

describe("configured Token Issuance Policy", () => {
  it("contains exactly the independently expected Permit Statements", () => {
    expect(tokenIssuancePolicy.permitStatements).toEqual(
      configuredPermitStatementExpectations.map((expectation) => ({
        permissions: expectation.permissions,
        resource: requestForExpectation(expectation, expectation.permissions).resource,
        subjectToken: {
          claimPredicates: [
            {
              claimName: "repository",
              expectedValue: expectation.workflowRepositoryFullName,
              kind: "claim-equals",
            },
            {
              claimName: "event_name",
              expectedValues: expectation.eventNames,
              kind: "claim-one-of",
            },
            {
              claimName: "ref_type",
              expectedValue: "branch",
              kind: "claim-equals",
            },
            {
              claimName: "ref",
              expectedValue: "refs/heads/main",
              kind: "claim-equals",
            },
            {
              claimName: "workflow_ref",
              expectedValue: expectation.workflowRef,
              kind: "claim-equals",
            },
          ],
          issuer: githubActionsOidcProviderRegistration.issuer,
        },
      })),
    );
    expect(tokenIssuancePolicy.permitStatements).toHaveLength(16);
  });

  it("permits every configured event with its exact request", () => {
    let acceptedEvents = 0;

    for (const expectation of configuredPermitStatementExpectations) {
      for (const eventName of expectation.eventNames) {
        expect(
          tokenIssuancePolicyPermits(
            tokenIssuancePolicy,
            subjectTokenForExpectation(expectation, { event_name: eventName }),
            requestForExpectation(expectation, expectation.permissions),
          ),
          `${expectation.workflowRef}: ${eventName}`,
        ).toBe(true);
        acceptedEvents += 1;
      }
    }

    expect(acceptedEvents).toBe(29);
  });

  it("does not permit permissions beyond each configured expectation", () => {
    let permissionDenials = 0;

    for (const expectation of configuredPermitStatementExpectations) {
      const subjectToken = subjectTokenForExpectation(expectation);

      for (const permissionName of standardPermissionNames) {
        const requestedLevel =
          expectation.permissions[permissionName] === undefined ? "read" : "admin";
        const permissions: GitHubInstallationPermissions = {
          [permissionName]: requestedLevel,
        };

        expect(
          tokenIssuancePolicyPermits(
            tokenIssuancePolicy,
            subjectToken,
            requestForExpectation(expectation, permissions),
          ),
          `${expectation.workflowRef}: ${permissionName}:${requestedLevel}`,
        ).toBe(false);
        permissionDenials += 1;
      }

      expect(
        tokenIssuancePolicyPermits(
          tokenIssuancePolicy,
          subjectToken,
          requestForExpectation(expectation, { issues: "read" }),
        ),
        `${expectation.workflowRef}: issues:read`,
      ).toBe(false);
      permissionDenials += 1;
    }

    expect(permissionDenials).toBe(16 * 4);
  });

  it("does not permit issuer, selected-Claim, Claim-type, or Repository Resource mutations", () => {
    let mutations = 0;
    const nonMatchingClaimValues: readonly unknown[] = ["unconfigured", null, false, 123, [], {}];

    for (const expectation of configuredPermitStatementExpectations) {
      for (const claimName of [
        "repository",
        "event_name",
        "ref_type",
        "ref",
        "workflow_ref",
      ] as const) {
        for (const claimValue of nonMatchingClaimValues) {
          expect(
            tokenIssuancePolicyPermits(
              tokenIssuancePolicy,
              subjectTokenForExpectation(expectation, { [claimName]: claimValue }),
              requestForExpectation(expectation, expectation.permissions),
            ),
            `${expectation.workflowRef}: ${claimName}=${JSON.stringify(claimValue)}`,
          ).toBe(false);
          mutations += 1;
        }

        expect(
          tokenIssuancePolicyPermits(
            tokenIssuancePolicy,
            withoutClaim(subjectTokenForExpectation(expectation), claimName),
            requestForExpectation(expectation, expectation.permissions),
          ),
          `${expectation.workflowRef}: missing ${claimName}`,
        ).toBe(false);
        mutations += 1;
      }

      for (const [resourceRepositoryFullName, mutationName] of [
        [expectation.resourceRepositoryFullName.replace("/", "-other/"), "resource owner"],
        [`${expectation.resourceRepositoryFullName}-other`, "resource repository"],
      ] as const) {
        expect(
          tokenIssuancePolicyPermits(
            tokenIssuancePolicy,
            subjectTokenForExpectation(expectation),
            requestForExpectation(expectation, expectation.permissions, resourceRepositoryFullName),
          ),
          `${expectation.workflowRef}: ${mutationName}`,
        ).toBe(false);
        mutations += 1;
      }

      expect(
        tokenIssuancePolicyPermits(
          tokenIssuancePolicy,
          subjectTokenForExpectation(
            expectation,
            {},
            { issuer: "https://unconfigured-issuer.example" },
          ),
          requestForExpectation(expectation, expectation.permissions),
        ),
        `${expectation.workflowRef}: issuer`,
      ).toBe(false);
      mutations += 1;
    }

    expect(mutations).toBe(16 * (5 * 7 + 2 + 1));
  });

  it("permits every legacy, immutable, customized, missing, and malformed sub form", () => {
    for (const expectation of configuredPermitStatementExpectations) {
      const subjectTokens = [
        ["legacy", subjectTokenForExpectation(expectation)],
        [
          "immutable",
          subjectTokenForExpectation(expectation, {
            sub: `repo:${expectation.workflowRepositoryFullName.replace("/", "@555555/")}@123456789:ref:refs/heads/main`,
          }),
        ],
        [
          "customized",
          subjectTokenForExpectation(expectation, { sub: `custom:${expectation.workflowRef}` }),
        ],
        ["missing", withoutClaim(subjectTokenForExpectation(expectation), "sub")],
        ["malformed", subjectTokenForExpectation(expectation, { sub: 123 })],
      ] as const;

      for (const [subForm, subjectToken] of subjectTokens) {
        expect(
          tokenIssuancePolicyPermits(
            tokenIssuancePolicy,
            subjectToken,
            requestForExpectation(expectation, expectation.permissions),
          ),
          `${expectation.workflowRef}: ${subForm}`,
        ).toBe(true);
      }
    }
  });
});

function withoutClaim<
  ClaimName extends string,
  SubjectToken extends ReturnType<typeof subjectTokenForExpectation>,
>(subjectToken: SubjectToken, claimName: ClaimName): SubjectToken {
  const claims = { ...subjectToken.claims };
  delete claims[claimName];

  return { ...subjectToken, claims: Object.freeze(claims) };
}

